    return [chk('shots recovered', [r[1] for r in res] == ['A'] * 10 + ['B'] * 10, [r[1] for r in res]), chk('MAD < 15 = full frame use', max((r[0] for r in res)) < 15, max((r[0] for r in res))), chk('linear fit gives offset c = 1.3', near(-icpt, 1.3, 0.05) and near(slope, 1, 0.02), (slope, -icpt))]

def card(work):
    edl = [{'src_in': 0.0, 'src_out': 4.0}, {'src_in': 6.0, 'src_out': 10.0}]
