    def src_to_prog(ts):
        p = 0.0
        for c in edl:
            if c['src_in'] <= ts < c['src_out']:
                return p + ts - c['src_in']
            p += c['src_out'] - c['src_in']
        return None
    words = [{'w': 'a', 'src': 1.5}, {'w': 'b', 'src': 5.0}, {'w': 'c', 'src': 7.25}]
    mapped = {w['w']: src_to_prog(w['src']) for w in words}
